<script lang="ts">
 import {onMount} from 'svelte';import {socket} from '$lib/socket';import {Activity,Radio,Users,Send,Wifi,WifiOff,Clock3,Hash,ChevronLeft,ChevronRight,Terminal,Zap,Globe2,Filter,Plus,LogIn,LogOut,CheckCircle2,AlertCircle,RefreshCw} from 'lucide-svelte';
 type Evt={eventId:string;eventType:string;timestamp:string;userId:string;payload:Record<string,unknown>;roomId?:string};type User={userId:string;connections:number;status:string};
 const API='http://localhost:4000';let connected=false;let reconnecting=false;let socketId='';let events:Evt[]=[];let users:User[]=[];let page=1;let pages=1;let total=0;let filter='ALL';let eventType='MESSAGE_CREATED';let userId='guest-'+Math.random().toString(36).slice(2,7);let payload='{"text":"Hello from Pulse!","priority":"normal"}';let roomId='engineering';let joinedRooms:string[]=[];let status='';let statusOk=false;let loading=false;let now=new Date();
 const types=['USER_JOINED','USER_LEFT','MESSAGE_CREATED','SYSTEM_NOTIFICATION','TASK_UPDATED','CUSTOM_EVENT'];
 async function loadHistory(){try{const q=new URLSearchParams({page:String(page),limit:'12'});if(filter!=='ALL')q.set('type',filter);const r=await fetch(`${API}/api/events?${q}`);if(!r.ok)throw new Error('History unavailable');const d=await r.json();events=d.items;pages=d.pages;total=d.total;}catch(e){status=e instanceof Error?e.message:'Could not load events';statusOk=false;}}
 async function loadUsers(){try{const r=await fetch(`${API}/api/users/online`);const d=await r.json();users=d.users??[];}catch{users=[];}}
 function connect(){socket.auth={userId};reconnecting=false;socket.connect();}
 function publish(){let parsed:Record<string,unknown>;try{parsed=JSON.parse(payload);if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error();}catch{status='Payload must be a valid JSON object';statusOk=false;return;}loading=true;socket.timeout(5000).emit('event:publish',{eventType,userId,payload:parsed,...(joinedRooms.length?{roomId:joinedRooms[0]}:{})},(err:Error|null,ack:{ok:boolean;data?:Evt;error?:string})=>{loading=false;if(err||!ack?.ok){status=ack?.error??'Acknowledgement timed out';statusOk=false;}else{status=`Published ${ack.data?.eventId.slice(0,8)} successfully`;statusOk=true;}});}
 function room(join:boolean){socket.timeout(5000).emit(join?'room:join':'room:leave',{roomId},(err:Error|null,ack:{ok:boolean;error?:string})=>{if(err||!ack?.ok){status=ack?.error??'Room request failed';statusOk=false;return;}joinedRooms=join?[...new Set([...joinedRooms,roomId])]:joinedRooms.filter(r=>r!==roomId);status=join?`Joined #${roomId}`:`Left #${roomId}`;statusOk=true;});}
 function time(value:string){return new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});}function style(type:string){return type==='MESSAGE_CREATED'?'violet':type==='USER_JOINED'?'green':type==='USER_LEFT'?'red':type==='TASK_UPDATED'?'blue':type==='SYSTEM_NOTIFICATION'?'amber':'slate';}
 onMount(()=>{void loadHistory();void loadUsers();connect();const onReady=(d:{socketId:string})=>{connected=true;reconnecting=false;socketId=d.socketId;void loadUsers();};const onDown=()=>{connected=false;reconnecting=true;};const onEvent=(e:Evt)=>{events=[e,...events.filter(x=>x.eventId!==e.eventId)].slice(0,80);total++;};const onJoin=()=>void loadUsers();const onLeave=()=>void loadUsers();socket.on('connect',()=>{connected=true;reconnecting=false;});socket.on('disconnect',onDown);socket.on('connect_error',onDown);socket.on('connection:ready',onReady);socket.on('event:new',onEvent);socket.on('presence:joined',onJoin);socket.on('presence:left',onLeave);const interval=setInterval(()=>{void loadUsers();},15000);return()=>{clearInterval(interval);socket.disconnect();socket.off('connect');socket.off('disconnect',onDown);socket.off('connect_error',onDown);socket.off('connection:ready',onReady);socket.off('event:new',onEvent);socket.off('presence:joined',onJoin);socket.off('presence:left',onLeave);};});
 $: onlineCount=users.length;
</script>
<svelte:head><title>Pulse — Real-time Event Feed</title><meta name="description" content="Live event streaming and presence dashboard"/></svelte:head>
<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-icon"><Activity size={21}/></div><div><strong>pulse<span>.</span></strong><small>EVENT PLATFORM</small></div></div><div class="workspace"><span class="workspace-dot"></span><div><b>Acme Workspace</b><small>Developer environment</small></div><span class="chev">⌄</span></div><div class="nav-label">WORKSPACE</div><a class="nav active"><Activity size={17}/> Live event feed <span class="live-dot"></span></a><a class="nav" href="#presence"><Users size={17}/> User presence</a><a class="nav" href="#publisher"><Send size={17}/> Event publisher</a><a class="nav" href="#rooms"><Hash size={17}/> Rooms</a><div class="nav-label second">SYSTEM</div><div class="side-card"><div class="side-card-head"><span class="pulse-ring"></span> System status</div><div class="side-status"><i class="ok-dot"></i> API operational</div><div class="side-status"><i class="ok-dot"></i> Event stream active</div><div class="side-status"><i class="ok-dot"></i> Database connected</div></div><div class="sidebar-bottom"><div class="avatar">{userId.slice(0,1).toUpperCase()}</div><div><b>{userId}</b><small>Workspace member</small></div><span class="more">···</span></div></aside>
<main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <b>Live overview</b></div><div class="top-actions"><div class:connected class="connection"><span></span>{connected?'Connected':reconnecting?'Reconnecting':'Disconnected'}</div><button class="icon-btn" onclick={()=>{void loadHistory();void loadUsers();}} aria-label="Refresh"><RefreshCw size={16}/></button><div class="avatar small-avatar">{userId.slice(0,1).toUpperCase()}</div></div></header>
<section class="page-head"><div><div class="eyebrow"><span class="eyebrow-line"></span> REAL-TIME INFRASTRUCTURE</div><h1>Event <em>Overview</em></h1><p>Monitor, publish, and manage events across your connected ecosystem.</p></div><div class="head-right"><div class="date-chip"><Clock3 size={15}/>{now.toLocaleDateString([], {month:'short',day:'numeric',year:'numeric'})}</div><button class="primary-btn" onclick={()=>document.getElementById('publisher')?.scrollIntoView({behavior:'smooth'})}><Plus size={16}/> Create event</button></div></section>
<section class="stats"><div class="stat-card"><div class="stat-top"><span>Total events</span><div class="stat-icon purple"><Activity size={17}/></div></div><div class="stat-value">{total.toLocaleString()}</div><div class="stat-foot"><span class="trend">↗ Live</span> persisted events</div></div><div class="stat-card"><div class="stat-top"><span>Online users</span><div class="stat-icon green"><Users size={17}/></div></div><div class="stat-value">{onlineCount.toString().padStart(2,'0')}</div><div class="stat-foot"><span class="trend">● Active</span> connected identities</div></div><div class="stat-card"><div class="stat-top"><span>Socket status</span><div class="stat-icon blue"><Radio size={17}/></div></div><div class="stat-value status-value">{connected?'Healthy':reconnecting?'Retrying':'Offline'}</div><div class="stat-foot">{socketId?`ID ${socketId.slice(0,12)}…`:'Waiting for connection'}</div></div><div class="stat-card"><div class="stat-top"><span>Active rooms</span><div class="stat-icon amber"><Hash size={17}/></div></div><div class="stat-value">{joinedRooms.length.toString().padStart(2,'0')}</div><div class="stat-foot">Your room subscriptions</div></div></section>
<div class="content-grid"><section class="panel feed-panel"><div class="panel-head"><div><div class="panel-title"><span class="live-pulse"></span> Live event stream</div><p>Incoming events from your workspace</p></div><div class="feed-tools"><span class="stream-label">LIVE STREAM</span><button class="icon-btn" onclick={()=>void loadHistory()} aria-label="Reload events"><RefreshCw size={15}/></button></div></div><div class="filter-row"><div class="filter-label"><Filter size={14}/> Filter</div><select bind:value={filter} onchange={()=>{page=1;void loadHistory();}}><option value="ALL">All event types</option>{#each types as t}<option value={t}>{t}</option>{/each}</select><span class="event-count">{events.length} events shown</span></div><div class="event-list">{#each events as event (event.eventId)}<article class="event-row"><div class="event-marker {style(event.eventType)}"><span></span></div><div class="event-main"><div class="event-line"><span class="event-type {style(event.eventType)}">{event.eventType}</span><span class="event-time">{time(event.timestamp)}</span></div><div class="event-meta"><span><Users size={12}/>{event.userId}</span>{#if event.roomId}<span><Hash size={12}/>{event.roomId}</span>{/if}<span class="event-id">{event.eventId.slice(0,8)}</span></div><pre>{JSON.stringify(event.payload,null,2)}</pre></div></article>{:else}<div class="empty"><div class="empty-icon"><Radio size={22}/></div><b>No events yet</b><span>Publish an event to see it appear here in real time.</span></div>{/each}</div><div class="pagination"><span>Showing <b>{events.length}</b> of <b>{total}</b> events</span><div><button class="page-btn" disabled={page<=1} onclick={()=>{page--;void loadHistory();}}><ChevronLeft size={15}/></button><span class="page-number">{page} / {Math.max(1,pages)}</span><button class="page-btn" disabled={page>=pages} onclick={()=>{page++;void loadHistory();}}><ChevronRight size={15}/></button></div></div></section>
<div class="right-column"><section class="panel presence-panel" id="presence"><div class="panel-head compact"><div><div class="panel-title">Online users <span class="count-pill">{onlineCount}</span></div><p>Active connections right now</p></div><span class="online-indicator">● LIVE</span></div><div class="user-list">{#each users as user}<div class="user-row"><div class="user-avatar">{user.userId.slice(0,1).toUpperCase()}</div><div class="user-info"><b>{user.userId}</b><small>{user.connections} connection{user.connections===1?'':'s'}</small></div><span class="user-online"></span></div>{:else}<div class="no-users"><Users size={20}/><span>No other users online</span><small>Open another browser tab with a different user ID.</small></div>{/each}</div><div class="presence-foot"><span><i class="ok-dot"></i> Presence synchronized</span><span>Auto refresh · 15s</span></div></section>
<section class="panel publisher-panel" id="publisher"><div class="panel-head compact"><div><div class="panel-title">Publish an event</div><p>Send an event to connected clients</p></div><div class="stat-icon purple"><Send size={16}/></div></div><label>EVENT TYPE</label><select bind:value={eventType}>{#each types as t}<option value={t}>{t}</option>{/each}</select><label>USER ID</label><input bind:value={userId} maxlength="100"/><label>JSON PAYLOAD</label><textarea bind:value={payload} spellcheck="false"></textarea><button class="publish-btn" disabled={!connected||loading} onclick={publish}><Send size={15}/>{loading?'Publishing…':'Publish event'} <span>↗</span></button>{#if status}<div class:success={statusOk} class="feedback">{#if statusOk}<CheckCircle2 size={14}/>{:else}<AlertCircle size={14}/>{/if}{status}</div>{/if}<div class="ack-note"><Zap size={13}/> Delivery acknowledgement · 5s timeout</div></section>
<section class="panel room-panel" id="rooms"><div class="panel-head compact"><div><div class="panel-title">Room subscriptions</div><p>Targeted event channels</p></div><div class="stat-icon amber"><Hash size={16}/></div></div><label>ROOM IDENTIFIER</label><div class="room-input"><input bind:value={roomId} placeholder="e.g. engineering"/><button class="join-btn" disabled={!connected||!roomId.trim()||joinedRooms.includes(roomId)} onclick={()=>room(true)}><LogIn size={14}/></button></div>{#each joinedRooms as room}<div class="joined-room"><span><i class="ok-dot"></i> #{room}</span><button onclick={()=>{roomId=room;room(false);}} aria-label="Leave room"><LogOut size={14}/></button></div>{:else}<div class="room-hint">You haven't joined any rooms yet.</div>{/each}</section></div></div>
<footer><span><span class="footer-brand">pulse.</span> Real-time Event Feed Platform</span><span><Globe2 size={13}/> Socket.IO · Redis Adapter · PostgreSQL</span><span>Built for developers <span class="heart">♥</span></span></footer></main></div>
